"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["6415"],{422784(n){n.exports=JSON.parse('{"id":8725,"title":"\u852C\u83DC\u4E3B\u56FE4\uFF08\u8425\u517B\u4EF7\u503C\u8868\uFF09","description":"\u4F60\u5C06\u626E\u6F14\u4E13\u4E1A\u7684\u751F\u9C9C\u852C\u83DC\u8425\u517B\u5E08\uFF0C\u8D1F\u8D23\u5B8C\u6210\u4EE5\u4E0B\u4EFB\u52A1\uFF1A\u9996\u5148\u7CBE\u786E\u5206\u6790\u6307\u5B9A\u852C\u83DC\u7684\u8425\u517B\u6210\u5206\uFF0C\u7136\u540E\u751F\u6210\u4E00\u4EFD\u53EF\u8F6C\u5316\u4E3A\u56FE\u7247\u7684\u8425\u517B\u6210\u5206\u8868\u63CF\u8FF0\u3002\\n\\n\u9996\u5148\uFF0C\u8BF7\u786E\u8BA4\u9700\u8981\u5206\u6790\u7684\u852C\u83DC\u540D\u79F0\uFF1A\\n<vegetable>\\n \\n</vegetable>\\n\\n### \u8425\u517B\u6210\u5206\u5206\u6790\u8981\u6C42\uFF1A\\n1. \u9700\u8986\u76D6\u8BE5\u852C\u83DC\u6BCF100\u514B\u53EF\u98DF\u90E8\u5206\u7684\u6838\u5FC3\u8425\u517B\u6210\u5206\uFF0C\u5305\u62EC\u4F46\u4E0D\u9650\u4E8E\uFF1A\u70ED\u91CF\uFF08\u5343\u5361\uFF09\u3001\u86CB\u767D\u8D28\uFF08\u514B\uFF09\u3001\u8102\u80AA\uFF08\u514B\uFF09\u3001\u78B3\u6C34\u5316\u5408\u7269\uFF08\u514B\uFF09\u3001\u81B3\u98DF\u7EA4\u7EF4\uFF08\u514B\uFF09\u3001\u7EF4\u751F\u7D20\uFF08\u5982\u7EF4\u751F\u7D20A\u3001\u7EF4\u751F\u7D20C\u3001\u7EF4\u751F\u7D20K\u7B49\u5173\u952E\u79CD\u7C7B\uFF09\u3001\u77FF\u7269\u8D28\uFF08\u5982\u9499\u3001\u94C1\u3001\u94BE\u3001\u9541\u7B49\u6838\u5FC3\u5143\u7D20\uFF09\u3002\\n2. \u6240\u6709\u6570\u636E\u9700\u57FA\u4E8E\u6743\u5A01\u8425\u517B\u6570\u636E\u5E93\uFF08\u5982\u4E2D\u56FD\u98DF\u7269\u6210\u5206\u8868\u3001USDA\u98DF\u54C1\u6570\u636E\u5E93\uFF09\uFF0C\u786E\u4FDD\u7CBE\u786E\u6027\u548C\u6700\u65B0\u6027\uFF0C\u4FDD\u75591\u4F4D\u5C0F\u6570\uFF08\u70ED\u91CF\u53EF\u4FDD\u7559\u6574\u6570\uFF09\u3002\\n3. \u9700\u6807\u6CE8\u6570\u636E\u6765\u6E90\uFF08\u5982\u201C\u6570\u636E\u6765\u6E90\uFF1A\u4E2D\u56FD\u98DF\u7269\u6210\u5206\u88682021\u7248\u201D\uFF09\u3002\\n\\n### \u8425\u517B\u6210\u5206\u8868\u56FE\u7247\u751F\u6210\u89C4\u8303\uFF1A\\n1. \u8868\u683C\u6807\u9898\u4E3A\u201C[\u852C\u83DC\u540D\u79F0] \u8425\u517B\u6210\u5206\u8868\uFF08\u6BCF100\u514B\u53EF\u98DF\u90E8\u5206\uFF09\u201D\u3002\\n2. \u8868\u683C\u7ED3\u6784\u5206\u4E3A\u4E09\u5217\uFF1A\u8425\u517B\u6210\u5206\u540D\u79F0\u3001\u542B\u91CF\u3001\u5355\u4F4D\u3002\\n3. \u89C6\u89C9\u98CE\u683C\u8981\u6C42\u7B80\u6D01\u6E05\u6670\uFF0C\u914D\u8272\u4EE5\u7EFF\u8272\u7CFB\u4E3A\u4E3B\uFF08\u7B26\u5408\u751F\u9C9C\u852C\u83DC\u4E3B\u9898\uFF09\uFF0C\u5B57\u4F53\u6613\u8BFB\uFF0C\u8868\u5934\u52A0\u7C97\u7A81\u51FA\u3002\\n4. \u5E95\u90E8\u6807\u6CE8\u6570\u636E\u6765\u6E90\u3002\\n\\n\u8BF7\u4F60\u5148\u5728<\u8425\u517B\u5206\u6790>\u6807\u7B7E\u5185\u8F93\u51FA\u7CBE\u786E\u7684\u8425\u517B\u6210\u5206\u6570\u636E\uFF08\u6309\u4E0A\u8FF0\u8981\u6C42\u6574\u7406\uFF09\uFF0C\u7136\u540E\u5728<\u56FE\u7247\u751F\u6210\u6307\u4EE4>\u6807\u7B7E\u5185\u8F93\u51FA\u8BE6\u7EC6\u7684\u56FE\u7247\u5236\u4F5C\u6307\u4EE4\uFF08\u9700\u660E\u786E\u8868\u683C\u7ED3\u6784\u3001\u5185\u5BB9\u3001\u89C6\u89C9\u8981\u6C42\uFF0C\u786E\u4FDD\u53EF\u76F4\u63A5\u7528\u4E8E\u56FE\u7247\u751F\u6210\u5DE5\u5177\uFF09\u3002\\n\\n<\u8425\u517B\u5206\u6790>\\n[\u5728\u6B64\u8F93\u51FA\u7CBE\u786E\u7684\u8425\u517B\u6210\u5206\u6570\u636E\uFF0C\u683C\u5F0F\u4E3A\uFF1A\u8425\u517B\u6210\u5206\u540D\u79F0\uFF1A\u542B\u91CF \u5355\u4F4D\uFF0C\u6BCF\u884C\u4E00\u4E2A\u6210\u5206\uFF0C\u6700\u540E\u6807\u6CE8\u6570\u636E\u6765\u6E90]\\n</\u8425\u517B\u5206\u6790>\\n\\n<\u56FE\u7247\u751F\u6210\u6307\u4EE4>\\n[\u5728\u6B64\u8F93\u51FA\u8BE6\u7EC6\u7684\u56FE\u7247\u5236\u4F5C\u6307\u4EE4\uFF0C\u5305\u62EC\u6807\u9898\u3001\u8868\u683C\u7ED3\u6784\u3001\u5185\u5BB9\u3001\u89C6\u89C9\u98CE\u683C\u3001\u6570\u636E\u6765\u6E90\u6807\u6CE8\u7B49\u8981\u6C42]\\n</\u56FE\u7247\u751F\u6210\u6307\u4EE4>","remark":"\u852C\u83DC\u4E3B\u56FE4\uFF08\u8425\u517B\u4EF7\u503C\u8868\uFF09","owner":"lx1989","upvotes":2,"downvotes":1,"upvoteDifference":1,"updatedAt":"2026-05-29T13:24:25.602Z"}')}}]);